const accountEvents=new BroadcastChannel('stylebyfire-accounts');
function clearAccountView(message=''){
 weeklyDraft=null;weekEditor=null;
 closeMannequin();
 outfitPreview.reset();buildMethod='stylist';pickerQuery='';autoMannequin=true;
 selectedItems.clear();reviewFilter='';availabilityFilter='';bulkUndo=null;bulkPreview=null;bulkDraft=null;webImportController?.abort();webImportController=null;busy=false;auth.user=null;state=null;outfit=null;locked=[];editor=null;itemDraft=null;importFiles=[];websiteDraft=null;delete window.pendingRestore;clearPhotoCache();$('#modal').close();authMode='login';renderAuth(message);
 history.replaceState(null,'','#sign-in');
}
accountEvents.onmessage=()=>clearAccountView('The account changed in another tab. Sign in to continue.');
window.addEventListener('focus',async()=>{if(!auth.user)return;try{const current=await api('/api/auth');if(current.user?.id!==auth.user?.id)clearAccountView('Your session changed. Sign in to continue.');}catch{}});

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
async function api(url,options={}){
 const headers=new Headers(options.headers);if(auth.user&&!url.startsWith('/api/auth'))headers.set('X-StyleByFire-Account',options.accountId||auth.user.id);
 const res=await fetch(url,{...options,headers});const data=await res.json();
 if(!res.ok){if((res.status===401||res.status===409)&&!url.startsWith('/api/auth')){clearAccountView(data.error);}throw Error(data.error||'The local app could not complete that action.');}return data;
}
function renderAuth(message=''){
 const registering=authMode==='register';
 $('#app').innerHTML=`<main class="auth-page"><section class="auth-intro"><a class="brand" href="#"><img src="/brand-flame.png" alt=""><span>Style<span class="brand-by">by</span>Fire<span class="brand-dot">.</span></span></a><p class="eyebrow">YOUR PERSONAL STYLE STUDIO</p><h1>A wardrobe.<br>A point of view.<br><em>All yours.</em></h1><p>Build outfits from the clothes you own. Explore a color story, find the finishing touches, and make every look your own.</p><div class="auth-palette" aria-label="Studio palette: midnight, cobalt, slate and silver"><span></span><span></span><span></span><span></span></div><small>Local accounts · Optional AI previews</small></section><section class="auth-card"><div class="auth-card-heading"><div><p class="eyebrow">WELCOME TO THE STUDIO</p><h2>${registering?'Create your account':'Welcome back'}</h2></div><img class="auth-monogram" src="/brand-monogram.png" alt="SF monogram" width="64" height="64"></div><p>${registering&&auth.needsSetup?'Your first personal account keeps any existing local wardrobe, including your notes and corrections.':registering?'Start a separate wardrobe with your own preferences.':'Sign in to your wardrobe on this computer.'}</p><div class="auth-tabs"><button data-action="auth-login" aria-pressed="${!registering}">Sign in</button><button data-action="auth-register" aria-pressed="${registering}">Create account</button></div><form id="auth-form" name="stylebyfire-sign-in" method="post" action="/api/auth/${registering?'register':'login'}" autocomplete="on">${registering?'<label>Your name<input name="displayName" autocomplete="name" maxlength="60" required></label>':''}<label>Username<input id="auth-username" name="username" autocomplete="username" minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,31}" autocapitalize="none" spellcheck="false" required><small>3–32 characters: letters, numbers, dots, underscores or hyphens. Start with a letter or number.</small></label><label>Password<input id="auth-password" name="password" type="password" autocomplete="${registering?'new-password':'current-password'}" minlength="8" maxlength="200" required>${registering?'<small>At least 8 characters. Stored locally; no email recovery.</small>':''}</label><p id="auth-error" class="auth-error" role="alert">${escape(message)}</p><button class="btn primary full" type="submit">${registering?'Create my account':'Sign in'}</button></form><div class="demo-entry"><h3>Meet Jamie Demo</h3><p>A fictional person with real product photos. First use downloads photos from clothing websites; they then stay available offline. Your own collection stays separate.</p>${button('Explore the demo wardrobe','auth-demo','secondary','spark')}</div></section></main>`;
}
async function loadAccount(){
 weeklyDraft=null;weekEditor=null;
 clearPhotoCache();state=validateState(await api('/api/state'));page='designer';category='All';query='';subfilter='';colorfilter='';favoritesOnly=false;locked=[];outfit=null;saveFailure=false;saveQueue=Promise.resolve();editor=null;itemDraft=null;delete window.pendingRestore;
 buildMethod='stylist';pickerQuery='';const accountId=auth.user.id;
 try{autoMannequin=localStorage.getItem('stylebyfire-auto-preview:'+accountId)!=='false';}catch{autoMannequin=true;}
 const previews=await outfitPreview.load(accountId);if(auth.user?.id!==accountId)return;
 let draft;try{draft=restoreOutfitDraft(JSON.parse(localStorage.getItem('stylebyfire-outfit:'+accountId)),state);}catch{}
 if(!draft){const recent=previews.find(p=>p.status==='complete'&&p.itemIds.every(id=>state.items.some(i=>i.id===id)));if(recent)draft=restoreOutfitDraft({...recent,method:'stylist'},state);}
 if(draft){mode=draft.mode;buildMethod=draft.method;locked=draft.locked;outfit=manualOutfit(draft.items,mode,state);}
 else if(state.items.length)outfit=generateOutfit(state.items,mode,state.rules[mode],state.profile,[],++seed);
 render();window.scrollTo(0,0);
 // A completed SPA navigation lets password managers recognize successful sign-in.
 history.replaceState(null,'','#designer');
}
async function authAction(endpoint,body){
 busy=true;try{auth=await api('/api/auth/'+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})});await loadAccount();accountEvents.postMessage('changed');}finally{busy=false;}
}
function openAccount(){openModal(`${modalHead('LOCAL ACCOUNT',escape(auth.user.displayName))}<p class="account-description">${auth.user.isDemo?'Jamie is a fictional test person using product photos from clothing websites. This sample wardrobe is separate from your personal collection.':'Your clothing, notes, saved looks and stylist preferences belong to this account on this computer.'}</p><p class="account-username">${auth.user.isDemo?'Demo account':'Username: '+escape(auth.user.username)}</p><div class="button-row">${button('Switch account / Sign out','sign-out','primary')}${button('Close','close-modal','secondary')}</div>`);}

function persist(){const snapshot=JSON.stringify(state),accountId=auth.user.id;const task=saveQueue.catch(()=>{}).then(()=>api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot,accountId}));saveQueue=task;task.then(()=>{saveFailure=false;updateSaveStatus();}).catch(e=>{saveFailure=true;updateSaveStatus();toast('Not saved: '+e.message);});return task;}
function updateSaveStatus(){const el=$('#save-status');if(el)el.innerHTML=saveFailure?'Changes not saved — export a backup':`${icon('lock',12)} Stored on this computer`;}
function photo(item,cls='',full=false){const a=item.adjustments;if(hasAdjustments(a))return `<canvas class="${cls}" data-photo="${escape(item.src)}" data-adjustments="${escape(JSON.stringify(a))}" role="img" aria-label="${escape(item.name)}"></canvas>`;return `<img class="${cls}" src="${escape(!full&&item.src.startsWith('/media/seed-')?item.src.replace('/media/','/thumbs/'):item.src)}" alt="${escape(item.name)}" loading="lazy">`;}
const button=(text,action,cls='secondary',ico='')=>`<button class="btn ${cls}" data-action="${action}">${ico?icon(ico,17):''}${text}</button>`;
function render(){
 if(!auth.user||!state)return renderAuth();
 const nav=[['wardrobe','grid','My wardrobe'],['designer','spark','Outfit designer'],['weekly','calendar','Weekly planner'],['saved','heart','Saved looks'],['stylist','sliders','Personal stylist'],['guidelines','book','Style playbook'],['studio','camera','Photo studio']];
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#wardrobe" data-nav="wardrobe" aria-label="StyleByFire home"><img src="/brand-flame.png" alt=""><span>Style<span class="brand-by">by</span>Fire<span class="brand-dot">.</span></span></a><div class="sidebar-label">YOUR STYLE, REIMAGINED</div><nav>${nav.map(([id,ic,label])=>`<button class="nav-item ${page===id?'active':''}" data-nav="${id}">${icon(ic)}<span>${label}</span>${id==='wardrobe'?`<small>${state.items.length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="private-label"><span class="status-dot"></span> A little space, just for you.</div><p>Your clothes. Your rules.<br>A fresh perspective, every day.</p><button class="text-button" data-action="backup">${icon('download',15)} Export wardrobe</button><button class="text-button muted" data-action="restore">Restore a backup</button><div class="save-status" id="save-status"></div></div></aside><div class="workspace"><header class="topbar"><span>THE EVERYDAY STYLE STUDIO</span><div><span class="local-badge">${icon('lock',12)} Local & private</span><button class="compact-backup icon-button" data-action="backup" aria-label="Export wardrobe backup">${icon('download',16)}</button><button class="compact-backup icon-button" data-action="restore" aria-label="Restore wardrobe backup">${icon('undo',16)}</button><button class="account-button" data-action="account" aria-label="Account: ${escape(auth.user.displayName)}"><span class="avatar">${escape(auth.user.displayName.slice(0,1))}</span><span>${escape(auth.user.displayName)}${auth.user.isDemo?' <small>DEMO</small>':''}</span></button></div></header><main id="main">${auth.user.isDemo?'<div class="demo-banner"><strong>Jamie Demo · fictional test account</strong><span>Real product photos for testing. Your personal wardrobe is separate.</span></div>':''}${categorySetupBanner()}${pageContent()}</main><footer>Made for the clothes you already love.<span class="footer-signature"><img class="footer-monogram" src="/brand-monogram.png" alt="" width="28" height="28">STYLEBYFIRE · PERSONAL EDITION</span></footer></div>`;
 updateSaveStatus();renderAdjustedImages();rememberOutfit();
 if(page==='designer')void outfitPreview.update(state,outfit?.items||[],mode,{automatic:buildMethod==='manual'&&autoMannequin});else outfitPreview.pause();
}
function pageContent(){return {wardrobe:wardrobePage,designer:designerPage,weekly:()=>weeklyPage(state,weeklyDraft,{escape,photo,icon}),saved:savedPage,stylist:stylistPage,guidelines:guidelinesPage,studio:studioPage}[page]();}

async function saveWeeklyForm(form,intent){
 const settings=weeklySettingsFromForm(new FormData(form),weeklyDraft||state.weeklyPlanner?.settings||defaultWeeklySettings(),state.weeklyPlanner?.plan);
 const accountId=auth.user.id,previousPlanner=state.weeklyPlanner;
 busy=true;form.querySelectorAll('button').forEach(button=>button.disabled=true);
 try{
  if(intent==='generate'){
   $('#weekly-save-note').textContent='Planning your week…';
   await new Promise(resolve=>setTimeout(resolve,30));
   if(auth.user?.id!==accountId)return;
  }
  const plan=intent==='generate'?generateWeeklyPlan(state,settings,++seed):state.weeklyPlanner?.plan||null;
  state.weeklyPlanner={version:1,settings,plan};
  await persist();
  if(auth.user?.id!==accountId)return;
  weeklyDraft=null;render();
  $(intent==='generate'?'.week-results':'.weekly-controls')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
  toast(intent==='generate'?'Your weekly outfits are saved. Expand each day for its pieces and style notes.':'Weekly settings saved. Generate a week to apply them to outfits.');
 }catch(error){if(auth.user?.id===accountId){state.weeklyPlanner=previousPlanner;const note=$('#weekly-save-note');if(note)note.textContent=error.message;}throw error;}
 finally{busy=false;if(form.isConnected)form.querySelectorAll('button').forEach(button=>button.disabled=false);}
}

function openWeeklyEditor(dayId,replaceId=null){
 const plan=state.weeklyPlanner?.plan,day=plan?.days.find(day=>day.id===dayId);
 if(!day)throw Error('Generate a week before editing its outfits.');
 const target=state.items.find(item=>item.id===replaceId&&day.itemIds.includes(item.id));
 weekEditor={dayId,itemIds:[...day.itemIds],replaceId:target?.id||null,category:target?.category||'All',query:'',showCurrent:!target&&day.itemIds.length<=6,baseline:JSON.stringify(plan)};
 renderWeeklyEditor();
}
function renderWeeklyEditor(focusSelector='',showCurrent){
 if(!weekEditor)return;
 const modal=$('#modal'),scroll=modal.open?modal.scrollTop:0;
 weekEditor.showCurrent=showCurrent??$('#modal .week-current-pieces')?.open??weekEditor.showCurrent;
 openModal(weeklyEditorMarkup(state,weekEditor,{escape,photo,modalHead}),'weekly-editor-modal');
 modal.scrollTop=scroll;
 if(focusSelector)$(focusSelector)?.focus({preventScroll:focusSelector!=='#week-piece-search'});
}
async function toggleWeeklyDayLock(dayId){
 const accountId=auth.user.id,previous=state.weeklyPlanner,oldDraft=weeklyDraft;
 const day=previous?.plan?.days.find(day=>day.id===dayId);
 if(!day)return;
 busy=true;
 try{
  state.weeklyPlanner=setWeeklyDayLock(previous,dayId,!day.locked);
  if(weeklyDraft&&!day.locked){weeklyDraft=structuredClone(weeklyDraft);Object.assign(weeklyDraft.days.find(day=>day.id===dayId),state.weeklyPlanner.settings.days.find(day=>day.id===dayId));}
  await persist();if(auth.user?.id!==accountId)return;
  render();$(`#week-${dayId} [data-week-lock]`)?.focus({preventScroll:true});
  toast(day.locked?'Day unlocked. It can change when you regenerate.':'Outfit locked. Regeneration will keep its pieces and style.');
 }catch(error){if(auth.user?.id===accountId){state.weeklyPlanner=previous;weeklyDraft=oldDraft;}throw error;}
 finally{busy=false;}
}
async function saveWeeklyPieces(){
 if(!weekEditor)return;
 if(weekEditor.baseline!==JSON.stringify(state.weeklyPlanner?.plan))throw Error('Your weekly plan changed. Close this editor and reopen the day before saving.');
 const accountId=auth.user.id,previous=state.weeklyPlanner.plan,dayId=weekEditor.dayId;
 const next=replaceWeeklyDay(state,previous,dayId,weekEditor.itemIds);
 busy=true;$$('#modal button').forEach(button=>button.disabled=true);
 try{
  state.weeklyPlanner.plan=next;await persist();if(auth.user?.id!==accountId)return;
  weekEditor=null;$('#modal').close();render();$(`#week-${dayId} [data-week-edit]`)?.focus({preventScroll:true});
  toast('Outfit updated in your weekly plan. Other days stay the same.');
 }catch(error){if(auth.user?.id===accountId){state.weeklyPlanner.plan=previous;renderWeeklyEditor();}throw error;}
 finally{busy=false;}
}

function bulkToolbar(){return `<section class="bulk-toolbar" aria-label="Wardrobe cleanup"><div class="button-row"><strong id="bulk-count">${selectedItems.size} selected</strong>${button('Select visible','select-visible')}${button('Clear selection','clear-selection')}${button('Edit selected','bulk-edit','primary')}${bulkUndo?button('Undo last bulk edit','bulk-undo'):''}</div><div class="form-grid"><label>Review filter<select id="review-filter">${[['','All pieces'],['unverified','Colors to verify'],['notes','Has correction notes'],['uncategorized','Missing subcategory'],['no-modes','Missing occasions']].map(([v,l])=>`<option value="${v}" ${reviewFilter===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Availability filter<select id="availability-filter"><option value="">Any availability</option>${Object.entries(AVAILABILITY).map(([v,l])=>`<option value="${v}" ${availabilityFilter===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="field-note">Selections stay selected across filters. Edit selected shows every affected piece before applying changes. Undo is available for the latest bulk edit in this session.</p></section>`;}
function bulkSelect(name,label,options){return `<label>${label}<select name="${name}"><option value="">Keep existing</option>${options.map(([v,l])=>`<option value="${escape(v)}">${escape(l)}</option>`).join('')}</select></label>`;}
function openBulkEdit(){
 const items=state.items.filter(i=>selectedItems.has(i.id));if(!items.length)return toast('Select pieces using the checkboxes on their photos.');
 bulkPreview=null;
 openModal(`${modalHead('WARDROBE CLEANUP',`Edit ${items.length} selected pieces`)}<details><summary>Selected pieces (${items.length})</summary><ul>${items.map(i=>`<li>${escape(i.name)}</li>`).join('')}</ul></details><p class="field-note">Only fields you choose will change. Notes are appended, and original photos are preserved.</p><form id="bulk-form"><div class="form-grid">${bulkSelect('color','Primary color',Object.keys(PALETTE).map(c=>[c,c]))}${bulkSelect('secondaryColor','Secondary color',[['__clear','Remove secondary color'],...Object.keys(PALETTE).map(c=>[c,c])])}${bulkSelect('pattern','Pattern',['Solid','Textured','Stripes','Checks','Argyle','Geometric','Diamond','Dots','Floral','Color block','Other'].map(c=>[c,c]))}${bulkSelect('colorVerified','Color verification',[['true','Mark checked against garment'],['false','Needs verification']])}${bulkSelect('availability','Availability',Object.entries(AVAILABILITY))}${bulkSelect('favorite','Favorites',[['true','Favorite'],['false','Not a favorite']])}${bulkSelect('formality','Formality',[[1,'1 · Relaxed'],[2,'2 · Smart casual'],[3,'3 · Tailored'],[4,'4 · Formal evening'],[5,'5 · Black tie']])}${bulkSelect('warmth','Warmth',[[0,'Lightweight'],[1,'Everyday'],[2,'Warm']])}${bulkSelect('rotation','Rotate photos',[[90,'90° clockwise'],[180,'180°'],[270,'90° counterclockwise']])}<label>Subcategory path<input name="subcategory" placeholder="Blank keeps existing"></label></div><label>Add tags<input name="addTags" placeholder="Comma-separated tags"></label><label>Remove tags<input name="removeTags" placeholder="Comma-separated tags"></label><label>Replace suitable occasions<input name="modes" placeholder="Blank keeps existing; e.g. Casual, Business"><small>Use Casual, Sport, Golf, Business, or Red carpet.</small></label><label>Append personal note<textarea name="notes" rows="2"></textarea></label><label>Append styling / color correction<textarea name="stylistNotes" rows="2"></textarea></label><button class="btn primary full" type="submit">Preview changes</button></form>`,'wide-modal');
 if(bulkDraft)for(const [key,value] of Object.entries(bulkDraft)){const input=$('#bulk-form [name="'+key+'"]');if(input)input.value=value;}
}
function previewBulkForm(data){
 bulkDraft=Object.fromEntries(data);
 const patch={};for(const key of ['color','secondaryColor','pattern','colorVerified','availability','favorite','formality','warmth','rotation','subcategory']){const value=data.get(key);if(value==='')continue;patch[key]=['formality','warmth','rotation'].includes(key)?Number(value):['colorVerified','favorite'].includes(key)?value==='true':key==='secondaryColor'&&value==='__clear'?'':key==='subcategory'?subpath(value):value;}
 patch.addTags=tags(data.get('addTags'));patch.removeTags=tags(data.get('removeTags'));patch.notes=data.get('notes');patch.stylistNotes=data.get('stylistNotes');if(data.get('modes').trim())patch.modes=data.get('modes').split(',').map(s=>s.trim()).filter(Boolean);
 const result=prepareBulkEdit(state,[...selectedItems],patch);bulkPreview={...result,baseline:JSON.stringify(state)};
 const fieldLabels={color:'Primary color',secondaryColor:'Secondary color',pattern:'Pattern',colorVerified:'Color verification',tags:'Tags',modes:'Suitable occasions',notes:'Personal notes',stylistNotes:'Styling corrections',adjustments:'Rotation',availability:'Availability',favorite:'Favorite',formality:'Formality',warmth:'Warmth',subcategory:'Subcategory'};
 const describe=(key,value)=>key==='adjustments'?`${value?.rotation||0}°`:key==='availability'?AVAILABILITY[value||'ready']:key==='colorVerified'?(value?'Verified':'Needs verification'):typeof value==='boolean'?(value?'Yes':'No'):Array.isArray(value)?value.join(', '):String(value??'None');
 const summary=result.undo.after.map((item,n)=>{const before=result.undo.before[n];return `<li><strong>${escape(item.name)}</strong><ul>${Object.keys(item).filter(k=>JSON.stringify(item[k])!==JSON.stringify(before[k])).map(k=>`<li>${escape(fieldLabels[k]||k)}: ${escape(describe(k,before[k]))} → ${escape(describe(k,item[k]))}</li>`).join('')}</ul></li>`;}).join('');
 openModal(`${modalHead('REVIEW BEFORE APPLYING','Preview bulk changes')}<p>${result.undo.after.length} selected pieces. Changes apply only after you press Apply.</p><ul class="bulk-preview">${summary}</ul><div class="button-row">${button('Apply changes','bulk-apply','primary')}${button('Back to editing','bulk-back')}${button('Cancel','close-modal')}</div>`,'wide-modal');
}
async function applyBulkPreview(){
 if(!bulkPreview)return;if(JSON.stringify(state)!==bulkPreview.baseline)throw Error('The wardrobe changed. Preview your edit again.');
 const previous=state,result=bulkPreview;busy=true;
 try{state=result.state;await persist();bulkUndo=result.undo;bulkPreview=null;selectedItems.clear();refreshOutfitAssessment();$('#modal').close();render();toast('Bulk changes saved. Undo is available in wardrobe cleanup.');}catch(error){state=previous;throw error;}finally{busy=false;}
}
async function applyBulkUndo(){const previous=state,next=undoBulkEdit(state,bulkUndo);busy=true;try{state=next;await persist();bulkUndo=null;refreshOutfitAssessment();render();toast('Bulk edit undone.');}catch(error){state=previous;throw error;}finally{busy=false;}}

function title(eyebrow,heading,description,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p class="subtitle">${description}</p></div>${action}</div>`;}
function filteredItems(){return state.items.filter(i=>needsReview(i,reviewFilter)&&(!availabilityFilter||(i.availability||'ready')===availabilityFilter)&&(category==='All'||i.category===category)&&(!favoritesOnly||i.favorite)&&(!subfilter||i.subcategory===subfilter||i.subcategory.startsWith(subfilter+' / '))&&(!colorfilter||itemColors(i).includes(colorfilter))&&(!query||[i.name,i.description||'',i.subcategory,...itemColors(i),...i.tags].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='favorites'?Number(b.favorite)-Number(a.favorite):sort==='newest'?state.items.indexOf(b)-state.items.indexOf(a):CATEGORIES.indexOf(a.category)-CATEGORIES.indexOf(b.category)||a.name.localeCompare(b.name));}
function wardrobePage(){return `${title('A CLOSET FULL OF POTENTIAL','Your wardrobe,<br><em>full of possibility.</em>',`${state.items.length} pieces. A thousand ways to make them yours.`,`<div class="button-row">${auth.user.canRefreshInventory?button('Refresh inventory','refresh-inventory','secondary','refresh'):''}${button('Import from website','web-import','secondary')}${button('Add clothing','import','primary','plus')}</div>`)}<section class="wardrobe-banner"><div class="banner-mark">${icon('spark',28)}</div><div><h3>Same clothes. A whole new look.</h3><p>Start with a favorite piece. Let the rest come together.</p></div><button class="banner-cta" data-nav="designer">Meet your next outfit ${icon('arrow',19)}</button></section><div class="collection-header"><h2>The collection <span>${state.items.length}</span></h2><button class="text-button" data-action="categories">${icon('folder',16)} Organize categories</button></div><div class="category-tabs" role="group" aria-label="Clothing category">${['All',...CATEGORIES].map(c=>`<button class="category-tab ${category===c?'selected':''}" data-category="${c}">${c==='All'?'All pieces':c}<span>${c==='All'?state.items.length:state.items.filter(i=>i.category===c).length}</span></button>`).join('')}</div><div class="filterbar"><label class="search-field">${icon('search',18)}<input id="search" placeholder="Find a piece, color, or tag…" value="${escape(query)}" aria-label="Search wardrobe"></label><select id="subfilter" aria-label="Filter by subcategory"><option value="">All subcategories</option>${subcategoryOptions(category==='All'?null:category,subfilter)}</select><select id="colorfilter" aria-label="Filter by color"><option value="">All colors</option>${Object.keys(PALETTE).map(c=>`<option ${c===colorfilter?'selected':''}>${c}</option>`).join('')}</select><button class="filter-favorite ${favoritesOnly?'on':''}" data-action="favorites-filter" aria-pressed="${favoritesOnly}" aria-label="Show favorites">${icon('heart',18)}</button><select id="sort" aria-label="Sort wardrobe"><option value="category">By category</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="favorites" ${sort==='favorites'?'selected':''}>Favorites first</option><option value="newest" ${sort==='newest'?'selected':''}>Newest first</option></select></div>${bulkToolbar()}<div id="collection-grid">${collectionGrid()}</div><div class="collection-note">${icon('sun',15)} Color names are starting estimates from your flash photos. Refine them in Photo studio.</div>`;}
function collectionGrid(){const items=filteredItems();return `<p class="results-label">${items.length} ${items.length===1?'piece':'pieces'}${favoritesOnly?' · Favorites':''}</p><div class="clothing-grid">${items.map(i=>itemCard(i)).join('')}${!query&&!subfilter&&!colorfilter&&!favoritesOnly&&!reviewFilter&&!availabilityFilter?`<button class="add-card" data-action="import">${icon('plus',28)}<strong>A new addition?</strong><span>Add a photo to your wardrobe</span></button>`:''}</div>${!items.length?`<div class="empty"><h3>${state.items.length?'Room for something new.':'Your wardrobe starts here.'}</h3><p>${query||subfilter||colorfilter||favoritesOnly?'Try another search or clear your filters.':'Add a photo to start this part of your collection.'}</p>${button('Clear filters','clear-filters')}</div>`:''}`;}
function pieceColors(item){return itemColors(item).map(c=>`<span class="piece-color"><span class="swatch" style="--swatch:${PALETTE[c]}"></span>${escape(c)}</span>`).join('');}
function secondaryColorField(item){return `<label>Pattern / secondary color<select name="secondaryColor"><option value="">None</option>${Object.keys(PALETTE).map(c=>`<option ${item.secondaryColor===c?'selected':''}>${c}</option>`).join('')}</select><small>Optional second color for matching, such as black patterning on a white shirt.</small></label>`;}
function refreshOutfitAssessment(){if(!outfit)return;const items=outfit.items.map(i=>state.items.find(current=>current.id===i.id)).filter(Boolean);outfit=buildMethod==='manual'?manualOutfit(items,mode,state):{items,errors:validateLocks(items,state.profile.avoidTags),...assessOutfit(items,mode,state.rules[mode],state.profile)};}
function itemCard(i,picker=false){
 const manual=picker&&buildMethod==='manual',chosen=manual?!!outfit?.items.some(item=>item.id===i.id):locked.includes(i.id);
 const unavailable=manual&&!chosen&&i.availability&&i.availability!=='ready';
 const action=picker?(manual?'choose-piece':'pin'):'edit',label=manual?(chosen?'Remove ':'Add '):picker?(chosen?'Unpin ':'Pin '):'Edit ';
 return `<article class="item-card ${chosen&&picker?'is-pinned':''}"><div class="item-image">${!picker?`<label class="bulk-select"><input type="checkbox" data-select-item="${i.id}" aria-label="Select ${escape(i.name)}" ${selectedItems.has(i.id)?'checked':''}></label>`:''}<button class="photo-button" data-${action}="${i.id}" aria-label="${label}${escape(i.name)}" ${picker?`aria-pressed="${chosen}"`:''} ${unavailable?'disabled':''}>${photo(i)}</button><span class="item-category">${escape(i.role==='dress'?'Top + Bottom':i.role==='outerwear'?'Top · Layer':i.role==='leggings'?'Bottom · Leggings':i.category)}</span><button class="heart ${i.favorite?'favorited':''}" data-favorite="${i.id}" aria-label="${i.favorite?'Unfavorite':'Favorite'} ${escape(i.name)}" aria-pressed="${i.favorite}">${icon('heart',17)}</button>${picker?`<span class="pin-indicator">${icon(chosen?'check':manual?'plus':'pin',15)} ${manual?(chosen?'In your outfit':unavailable?'Unavailable':'Add to outfit'):(chosen?'Required':'Pin piece')}</span>`:''}</div><div class="item-info"><h3>${escape(i.name)}</h3>${i.availability&&i.availability!=='ready'?`<span class="availability-badge">${escape(AVAILABILITY[i.availability])}</span>`:''}<div>${pieceColors(i)}<span class="dot-divider">·</span><span class="item-sub">${escape(i.subcategory.split(' / ').at(-1)||i.category)}</span></div></div></article>`;
}
function subcategoryOptions(cat,selected=''){const paths=new Set();for(const s of [...DEFAULT_SUBCATEGORIES,...state.subcategories,...state.items.map(i=>({category:i.category,path:i.subcategory}))])if(!cat||s.category===cat){const parts=s.path.split(' / ');for(let i=1;i<=parts.length;i++)paths.add(parts.slice(0,i).join(' / '));}return [...paths].filter(Boolean).sort().map(p=>`<option value="${escape(p)}" ${p===selected?'selected':''}>${escape(p)}</option>`).join('');}
function designerPage(){
 const manual=buildMethod==='manual';
 const pending=!manual&&outfit&&!outfit.errors.length&&locked.some(id=>!outfit.items.some(i=>i.id===id));
 const canSave=outfit&&outfit.items.length&&!outfit.errors.length&&!pending;
 return `<div class="designer-page"><header class="designer-intro"><h1>Your outfit, <em>in focus.</em></h1><p>See the complete look, then make every piece your own.</p></header>
 <div class="mode-tabs" role="group" aria-label="Outfit occasion">${MODES.map(m=>`<button data-mode="${m}" class="mode-tab ${mode===m?'selected':''}" aria-pressed="${mode===m}">${m==='Sport'?'Sport / active':m}</button>`).join('')}</div>
 <section class="outfit-workspace" id="outfit-workspace" aria-labelledby="outfit-title" tabindex="-1">
  <div class="outfit-workspace-header"><div><p class="eyebrow">${escape(mode.toUpperCase())} LOOK</p><h2 id="outfit-title">${outfit?.items.length?'Your outfit':'Start your next outfit'}</h2></div></div>
  <div id="outfit-preview">${outfitPreview.markup(!!outfit?.items.length)}</div>
  <div class="outfit-actions">${button('Choose pieces','build-manually','secondary','grid')}${button(manual?'Suggest the rest':outfit?'Remix this look':'Create a look','generate','primary','spark')}<button class="btn secondary" data-action="save-look" ${canSave?'':'disabled'}>${icon('heart',18)} Save this look</button></div>
  <div class="outfit-pieces-heading"><h3>The pieces in this look</h3><span>${manual?'Selected by you':'Styled with your preferences'}</span></div>
  <div id="outfit-result" aria-live="polite">${outfitResult()}</div>
  <div class="outfit-workspace-footer"><p>${manual?'Add or remove pieces in the manual builder below.':'Pin a piece to keep it in your next remix.'} Select an outfit photo for details.</p><button class="text-button" data-nav="guidelines">${icon('sliders',16)} Adjust style guidelines</button></div>
 </section>
 <section class="designer-main outfit-builder" id="clothing-picker" aria-labelledby="picker-title"><div class="section-top"><div><p class="eyebrow">MAKE IT YOUR OWN</p><h2 id="picker-title">Build your outfit</h2><p>${manual?'Choose each piece yourself. Your outfit updates as you select.':'Pin your favorites, then remix to let your stylist fill in the rest.'}</p></div><div class="button-row"><span class="pill">${manual?(outfit?.items.length||0)+' selected':locked.length+' pinned'}</span>${button('View outfit','view-outfit','secondary','hanger')}</div></div>
 <div class="builder-methods" role="group" aria-label="Outfit building method"><button data-build-method="manual" aria-pressed="${manual}">Choose every piece <span>Build manually</span></button><button data-build-method="stylist" aria-pressed="${!manual}">Style with suggestions <span>Pin pieces and remix</span></button></div>
 ${manual?`<div class="auto-preview-setting"><label class="check-row"><input type="checkbox" id="auto-mannequin" ${autoMannequin?'checked':''}>Automatically prepare mannequin updates</label><p>After you stop choosing for two seconds, a Codex request is prepared for the new look. Send it to Codex once; the finished image appears automatically.</p></div><div class="manual-builder-help"><p>Choose a new shirt, bottom, or shoe to replace that slot. Dresses replace a separate top and bottom. Combine as many accessories as you like, up to 20 total pieces.</p>${button('Start empty','clear-outfit','secondary')}</div>${outfit?.items.length?`<div class="locked-strip" aria-label="Your selected pieces">${outfit.items.map(i=>`<button data-choose-piece="${i.id}" class="chip" aria-label="Remove ${escape(i.name)} from outfit">${icon('check',12)} ${escape(i.name)} ×</button>`).join('')}</div>`:''}`:''}
 <label class="search-field builder-search">${icon('search',18)}<input id="picker-search" placeholder="Find a piece, color, or subcategory…" value="${escape(pickerQuery)}" aria-label="Search outfit pieces"></label>
 <div class="category-tabs compact" role="group" aria-label="Picker category">${['All',...CATEGORIES].map(c=>`<button class="category-tab ${category===c?'selected':''}" data-category="${c}" aria-pressed="${category===c}">${c==='All'?'All pieces':c}</button>`).join('')}</div>
 ${!manual&&locked.length?`<div class="locked-strip">${state.items.filter(i=>locked.includes(i.id)).map(i=>`<button data-pin="${i.id}" class="chip" aria-label="Unpin ${escape(i.name)}">${icon('pin',12)} ${escape(i.name)} ×</button>`).join('')}<button class="text-button" data-action="clear-pins">Clear pins</button></div>`:''}
 <div class="clothing-grid picker-grid" id="outfit-picker-grid">${renderPicker()}</div></section></div>`;
}

function outfitPiece(item){
 const role=slotFor(item)==='accessory'?ACCESSORY_LABELS[accessoryType(item)]:{top:'Top',dress:'Top + Bottom',layer:'Outer layer',bottom:'Bottom',leggings:'Leggings',cap:'Cap',socks:'Socks',shoes:'Shoes',accessory:'Accessory'}[slotFor(item)];
 const pinned=locked.includes(item.id);
 if(buildMethod==='manual')return `<article class="outfit-piece"><div class="outfit-piece-label">${escape(role)}</div><button class="outfit-piece-photo" data-edit="${item.id}" aria-label="View ${escape(item.name)} details">${photo(item,'',true)}</button><div class="outfit-piece-info"><h3>${escape(item.name)}</h3><div class="outfit-piece-meta"><span class="piece-colors">${pieceColors(item)}</span><button class="outfit-pin" data-choose-piece="${item.id}" aria-label="Remove ${escape(item.name)} from outfit">${icon('close',15)} Remove</button></div></div></article>`;
 return `<article class="outfit-piece ${pinned?'outfit-piece-pinned':''}"><div class="outfit-piece-label">${escape(role)}</div><button class="outfit-piece-photo" data-edit="${item.id}" aria-label="View ${escape(item.name)} details">${photo(item,'',true)}</button><div class="outfit-piece-info"><h3>${escape(item.name)}</h3><div class="outfit-piece-meta"><span class="piece-colors">${pieceColors(item)}</span><button class="outfit-pin" data-pin="${item.id}" aria-label="${pinned?'Unpin':'Pin'} ${escape(item.name)}" aria-pressed="${pinned}" title="${pinned?'Unpin this piece':'Keep this piece in remixes'}">${icon(pinned?'check':'pin',17)}<span>${pinned?'Pinned':'Pin'}</span></button></div></div></article>`;
}

function outfitResult(){
 const order=['cap','top','dress','layer','bottom','leggings','socks','shoes','accessory'];
 if(!outfit){
  const pinned=state.items.filter(i=>locked.includes(i.id)).sort((a,b)=>order.indexOf(slotFor(a))-order.indexOf(slotFor(b)));
  return `<div class="outfit-status-line"><p>${pinned.length?'Your pinned pieces are ready. Create a look to fill in the rest.':'Your outfit will appear here, with every piece large enough to see.'}</p></div>${pinned.length?`<div class="outfit-board">${pinned.map(outfitPiece).join('')}</div>`:`<div class="outfit-start"><div class="outfit-start-mark">${icon('hanger',46)}</div><div><h3>Start with what you love.</h3><p>Create a look now, or pin a favorite from your wardrobe below.</p></div>${button('Browse clothing','browse-clothing','secondary','grid')}</div>`}`;
 }
 if(outfit.errors.length)return `<div class="notice error"><strong>Adjust your starting pieces</strong>${outfit.errors.map(s=>`<p>${escape(s)}</p>`).join('')}</div>`;
 const pending=locked.some(id=>!outfit.items.some(i=>i.id===id));
 const colors=[...new Set(outfit.items.flatMap(itemColors))];
 const clothing=outfit.items.filter(i=>slotFor(i)!=='accessory').sort((a,b)=>order.indexOf(slotFor(a))-order.indexOf(slotFor(b)));
 const accessories=outfit.items.filter(i=>slotFor(i)==='accessory');
 return `<div class="outfit-status-line"><span class="look-status ${outfit.complete?'complete':''}">${icon(outfit.complete?'check':'hanger',17)} ${outfit.complete?'All essential slots filled':'A look in progress'}</span><span class="outfit-piece-count">${outfit.items.length} pieces${locked.length?` · ${locked.length} pinned`:''}</span></div>
 ${pending?`<div class="notice pending-notice" role="status"><strong>New starting pieces selected.</strong><p>Remix this look to include all your pinned pieces. Your current outfit stays visible until then.</p></div>`:''}
 ${colors.length?`<div class="outfit-palette"><span>Color story</span>${colors.map(c=>`<span class="palette-color"><span class="swatch" style="--swatch:${PALETTE[c]}"></span>${escape(c)}</span>`).join('')}</div>`:''}
 ${clothing.length?`<div class="outfit-board">${clothing.map(outfitPiece).join('')}</div>`:''}
 ${accessories.length?`<section class="outfit-accessories" aria-label="Selected accessories"><div class="accessory-heading"><h3>The finishing touches</h3><span>${accessories.length} ${accessories.length===1?'accessory':'accessories'} · part of this outfit</span></div><div class="outfit-board accessory-board">${accessories.map(outfitPiece).join('')}</div></section>`:''}
 ${outfit.missing.length?`<div class="notice missing-notice"><div><strong>Still needs ${outfit.missing.map(escape).join(', ')}</strong><p>Add suitable pieces for this mode to finish the outfit.</p></div>${button('Add clothing','import','secondary','plus')}</div>`:''}
 ${outfit.reasons.length||outfit.warnings.length?`<details class="outfit-guidance" open><summary>Stylist notes${outfit.warnings.length?` · ${outfit.warnings.length} ${outfit.warnings.length===1?'thing':'things'} to consider`:''}</summary><div class="outfit-guidance-body">${outfit.reasons.length?`<div><h3>Why these work together</h3>${outfit.reasons.map(r=>`<p>${icon('check',15)}${escape(r)}</p>`).join('')}</div>`:''}${outfit.warnings.length?`<div><h3>Things to consider</h3>${outfit.warnings.map(w=>`<p>${escape(w)}</p>`).join('')}</div>`:''}</div></details>`:''}`;
}

function scrollToDesignerSection(id){
 const target=document.getElementById(id);if(!target)return;
 target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
 if(id==='outfit-workspace')target.focus({preventScroll:true});
}

function savedPage(){return `${title('THE LOOKBOOK','Good looks, <em>on repeat.</em>','Save the combinations you love. Revisit, refine, and wear them again.',button('Design a look','go-designer','primary','plus'))}${state.looks.length?`<div class="look-grid">${state.looks.map(l=>{const pieces=l.itemIds.map(id=>state.items.find(i=>i.id===id)).filter(Boolean);const status=assessOutfit(pieces,l.mode,state.rules[l.mode],state.profile);return `<article class="saved-look"><div class="look-collage">${pieces.slice(0,4).map(i=>photo(i)).join('')}</div><div class="saved-body"><p class="eyebrow">${escape(l.mode)} · ${status.complete?'SLOTS FILLED':'IN PROGRESS'}</p><h2>${escape(l.name)}</h2><p>${pieces.length} pieces · ${new Date(l.createdAt).toLocaleDateString()}</p><div class="button-row"><button class="btn secondary" data-open-look="${l.id}">Open in designer ${icon('arrow',15)}</button><button class="text-button danger" data-delete-look="${l.id}">Remove</button></div></div></article>`;}).join('')}</div>`:`<div class="empty large">${icon('heart',46)}<h2>A home for your favorite combinations.</h2><p>Create a look in the designer, then save it here—even if it’s still a work in progress.</p>${button('Create your first look','go-designer','primary','spark')}</div>`}`;}
function stylistPage(){const p=state.profile;return `${title('YOUR PERSONAL STYLIST','A point of view.<br><em>Entirely yours.</em>','Set the preferences behind your recommendations. No prompts or code required.')}<form id="stylist-form" class="settings-layout"><section class="settings-card"><p class="eyebrow">01 / THE PERSONAL TOUCH</p><h2>Meet your stylist</h2><label>Stylist name<input name="name" value="${escape(p.name)}" maxlength="80" required></label><div class="form-grid"><label>Color direction<select name="palette"><option value="balanced" ${p.palette==='balanced'?'selected':''}>Balanced · neutral foundations</option><option value="tonal" ${p.palette==='tonal'?'selected':''}>Tonal · similar color families</option><option value="expressive" ${p.palette==='expressive'?'selected':''}>Expressive · mix color families</option></select></label><label>Outfit structure<select name="silhouette"><option value="either" ${p.silhouette==='either'?'selected':''}>Open to dresses or separates</option><option value="separates" ${p.silhouette==='separates'?'selected':''}>Prefer separate tops & bottoms</option><option value="dress" ${p.silhouette==='dress'?'selected':''}>Prefer dresses</option></select></label></div><label>Preferred tags<input name="preferredTags" value="${escape(p.preferredTags.join(', '))}" placeholder="minimal, tailored, colorful"><small>Give matching pieces a boost. Separate tags with commas.</small></label><label>Exclude tags<input name="avoidTags" value="${escape(p.avoidTags.join(', '))}" placeholder="itchy, uncomfortable, needs-repair"><small>Hard exclusions, including pinned pieces. Tags match exactly.</small></label><label class="check-row"><input type="checkbox" name="ignoreSockPatterns" ${p.ignoreSockPatterns?'checked':''}>Exclude socks from the pattern limit</label><p class="field-note">Applies to every occasion. Sock colors follow your color-limit preference; their patterns do not use up your pattern allowance.</p><label class="check-row"><input type="checkbox" name="ignoreNeutralColors" ${p.ignoreNeutralColors?'checked':''}>Exclude neutral colors from the color limit</label><p class="field-note">Your selected neutrals do not use your color allowance when exclusion is enabled. Applies to every occasion; all colors remain visible in the color story.</p><fieldset class="neutral-options"><legend>My neutral colors</legend><p class="field-note">These also define neutral foundations for balanced styling. Choose none to count every color.</p><div class="color-options">${Object.keys(PALETTE).map(c=>`<label><input type="checkbox" name="neutralColors" value="${c}" ${neutralColors(p).includes(c)?'checked':''}><span class="swatch" style="--swatch:${PALETTE[c]}"></span>${c}</label>`).join('')}</div><div class="button-row"><button type="button" class="text-button" data-action="neutral-defaults">Use default neutrals</button><button type="button" class="text-button" data-action="neutral-none">Clear selection</button></div></fieldset><label>Personal style notes<textarea name="notes" rows="3" placeholder="Ideas, inspirations, or fit reminders for yourself…">${escape(p.notes)}</textarea><small>A notebook for you. Recommendations use the controls and tags above.</small></label></section><section class="settings-card"><p class="eyebrow">02 / THE FINISHING TOUCHES</p><h2>Fine-tune the feeling</h2>${rangeField('favoriteBias','Reach for favorites',p.favoriteBias,0,10,'Fresh combinations','Trusted favorites')}${rangeField('adventure','Room to experiment',p.adventure,0,10,'Keep it familiar','Surprise me')}${rangeField('warmth','Preferred garment warmth',p.warmth,0,2,'Lightweight','Cozy')}<p class="field-note">Warmth comes from each item’s label. This is a preference, not a weather forecast.</p><div class="notice"><strong>Advice you can understand.</strong><p>Your stylist uses wardrobe labels, saved preferences, and editable mode guidelines. Every generated look explains the choices.</p></div><button class="btn primary full" type="submit">${icon('check',17)} Save stylist preferences</button></section></form>`;}
function rangeField(name,label,value,min,max,left,right){return `<label class="range-field">${label}<output>${value}</output><input type="range" aria-label="${escape(label)}" name="${name}" min="${min}" max="${max}" value="${value}"><span class="range-labels"><small>${left}</small><small>${right}</small></span></label>`;}
function guidelinesPage(){const r=state.rules[ruleMode];return `${title('THE STYLE PLAYBOOK','A little guidance.<br><em>Room to make it yours.</em>','Published dress-code guidance, translated into adjustable starting points.')}<div class="mode-tabs">${MODES.map(m=>`<button class="mode-tab ${ruleMode===m?'selected':''}" data-rule-mode="${m}">${m}</button>`).join('')}</div><form id="rules-form" class="settings-layout"><section class="settings-card"><p class="eyebrow">${escape(ruleMode)} / YOUR GUIDELINES</p><h2>Set the boundaries</h2><div class="form-grid"><label>Minimum formality<select name="minFormality">${formalityOptions(r.minFormality)}</select></label><label>Maximum formality<select name="maxFormality">${formalityOptions(r.maxFormality)}</select></label></div><p class="field-note">Unpinned suggestions must match the mode and this range. Pinned pieces stay, with conflicts explained.</p><div class="form-grid"><label>Preferred maximum patterns<input name="maxPatterns" type="number" min="0" max="8" value="${r.maxPatterns}" required></label><label>Preferred maximum colors<input name="maxColors" type="number" min="1" max="8" value="${r.maxColors}" required></label></div><p class="field-note">Color and pattern limits are flexible styling preferences, not universal dress-code rules.</p><p class="field-note">${state.profile.ignoreSockPatterns?'Sock patterns are excluded from this limit.':'Sock patterns count toward this limit.'} ${state.profile.ignoreNeutralColors?'Neutral colors are excluded from the color limit.':'All color families count toward the color limit.'} <button type="button" class="text-button" data-nav="stylist">Change in Personal stylist</button></p>${[['requireSocks','Require socks to complete the look'],['includeLayer','Suggest an outer layer'],['includeAccessory','Suggest accessories across available types']].map(([k,l])=>`<label class="check-row"><input type="checkbox" name="${k}" ${r[k]?'checked':''}>${l}</label>`).join('')}${ruleMode==='Golf'?golfControls(r):''}<label>Your course / event / workplace notes<textarea name="note" rows="3">${escape(r.note)}</textarea><small>Reference notes; encoded controls determine recommendations.</small></label><div class="button-row"><button class="btn primary" type="submit">Save guidelines</button>${button('Restore defaults','reset-rules','secondary')}</div></section><aside class="settings-card source-card"><p class="eyebrow">THE THINKING BEHIND THE LOOK</p><h2>Context makes the outfit.</h2><p>${escape(DEFAULT_RULES[ruleMode].note)}</p>${ruleMode==='Business'?'<p>For business formal, confirm a matching suit or a suitable formal business dress. The default here is business casual.</p>':''}${ruleMode==='Sport'?'<p>A sport coat is tailoring, not sportswear. Fabric performance and activity suitability need your confirmation.</p>':''}${ruleMode==='Golf'?golfGuide():''}<p>Clothing options are available to everyone. Your comfort, workplace, activity, and event invitation come first.</p><h4>Source reading</h4>${ruleMode==='Golf'?golfSourceLinks():`<a href="https://emilypost.com/advice/attire-guide-dress-codes-from-casual-to-white-tie" target="_blank" rel="noreferrer">Emily Post · Attire guide ↗</a><a href="https://emilypost.com/advice/business-casual-attire-guide" target="_blank" rel="noreferrer">Emily Post · Business casual ↗</a><a href="https://www.rei.com/learn/expert-advice/running-clothing.html" target="_blank" rel="noreferrer">REI · Running clothing ↗</a><a href="https://www.festival-cannes.com/en/faq/" target="_blank" rel="noreferrer">Festival de Cannes · Event dress code ↗</a><small>These sources inform the defaults; they do not endorse this app. Event rules may change.</small>`}</aside></form>`;}
function studioPage(){return `${title('THE PHOTO STUDIO','Real clothes.<br><em>Truer colors.</em>','Adjust everyday photos without changing your originals. No perfect lighting required.')}<section class="studio-intro"><div><h2>A useful reference, not a magic fix.</h2><p>Your background photo is saved for side-by-side comparison. Because the fabric is blue, it should not be treated as a neutral gray card. Flash glare and missing color detail cannot always be recovered.</p><div class="button-row">${button('Change background reference','reference','secondary','camera')}</div></div>${state.reference?`<img src="${escape(state.reference)}" alt="Your photography background reference">`:''}</section><div class="section-top"><h2>Choose a piece to refine</h2><span class="muted">Exposure · white balance · crop · color labels</span></div><div class="clothing-grid">${state.items.map(i=>`<article class="item-card"><button class="photo-button item-image" data-studio="${i.id}">${photo(i)}</button><div class="item-info"><h3>${escape(i.name)}</h3><button class="text-button" data-studio="${i.id}">${icon('sliders',14)} Edit photo & color</button></div></article>`).join('')}</div>`;}
function formalityOptions(selected){return ['Relaxed','Smart casual','Tailored / polished','Formal evening','Black-tie candidate'].map((n,i)=>`<option value="${i+1}" ${Number(selected)===i+1?'selected':''}>${i+1} · ${n}</option>`).join('');}
function openModal(html,cls=''){const d=$('#modal');d.className=cls;d.innerHTML=html;if(!d.open)d.showModal();renderAdjustedImages(d);}
function modalHead(eyebrow,title){return `<div class="modal-head"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;}
function modesChecks(selected){return `<fieldset class="mode-checks"><legend>Suitable for</legend>${MODES.map(m=>`<label><input type="checkbox" name="modes" value="${m}" ${selected.includes(m)?'checked':''}>${m}</label>`).join('')}</fieldset>`;}
function categoryFields(i){return `<div class="form-grid"><label>Category<select name="category" id="item-category">${CATEGORIES.map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Outfit role<select name="role" id="item-role">${roleOptions(i.category,i.role)}</select></label></div><label>Subcategory path<input name="subcategory" list="subcategory-list" value="${escape(i.subcategory)}" placeholder="Shirts / Button-down / Tuck-in"><datalist id="subcategory-list">${subcategoryOptions(i.category)}</datalist><small>Use / to create as many nested levels as you need.</small></label>`;}
function roleOptions(cat,role){return [['base','Standard piece'],...(cat==='Top'?[['outerwear','Outer layer'],['dress','Dress · covers Top + Bottom']]:cat==='Bottom'?[['leggings','Leggings · base or underlayer']]:[])].map(([v,t])=>`<option value="${v}" ${role===v?'selected':''}>${t}</option>`).join('');}
function openItem(id){const i=state.items.find(i=>i.id===id);if(!i)return;itemDraft=structuredClone(i);openModal(`${modalHead('IN YOUR WARDROBE','The finer details.')}<form id="item-form" data-id="${id}" class="item-editor"><div class="detail-photo"><div id="detail-image">${photo(i,'',true)}</div><div class="button-row rotate-controls"><button type="button" class="btn secondary" data-rotate-detail="${id}" data-turn="-90">${icon('undo',15)} Rotate left</button><button type="button" class="btn secondary" data-rotate-detail="${id}" data-turn="90">${icon('refresh',15)} Rotate right</button></div><p class="tiny">Save piece to keep the rotation. Your original stays unchanged.</p>${i.sourceUrl?`<a class="piece-source" href="${escape(i.sourceUrl)}" target="_blank" rel="noopener noreferrer">View original product${i.sourceName?` · ${escape(i.sourceName)}`:''}</a>`:''}<button type="button" class="btn secondary" data-studio="${id}">${icon('sliders',16)} Open photo studio</button></div><div class="detail-fields"><label>Piece name<input name="name" value="${escape(i.name)}" maxlength="200" required></label><label>Description<textarea name="description" rows="3" maxlength="2000" placeholder="A short description of the piece and its true color…">${escape(i.description||'')}</textarea></label>${categoryFields(i)}<div class="form-grid"><label>Color family<select name="color">${Object.keys(PALETTE).map(c=>`<option ${i.color===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Pattern<select name="pattern">${['Solid','Textured','Stripes','Checks','Argyle','Geometric','Diamond','Dots','Floral','Color block','Other'].map(p=>`<option ${i.pattern===p?'selected':''}>${p}</option>`).join('')}</select></label></div>${secondaryColorField(i)}<label>Availability<select name="availability">${Object.entries(AVAILABILITY).map(([v,l])=>`<option value="${v}" ${(i.availability||'ready')===v?'selected':''}>${l}</option>`).join('')}</select><small>Only ready pieces join new outfits. Archived pieces and their photos stay saved.</small></label><label class="check-row"><input type="checkbox" name="colorVerified" ${i.colorVerified?'checked':''}>I’ve checked this color label</label><div class="form-grid"><label>Formality<select name="formality">${formalityOptions(i.formality)}</select></label><label>Warmth<select name="warmth">${['Lightweight','Everyday','Warm'].map((v,n)=>`<option value="${n}" ${i.warmth===n?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Tags<input name="tags" value="${escape(i.tags.join(', '))}" placeholder="tailored, vintage, breathable"></label>${modesChecks(i.modes)}<label>Personal notes<textarea name="notes" rows="3" placeholder="Fit, comfort, memories, care reminders…">${escape(i.notes||'')}</textarea></label><label>Styling & color corrections<textarea name="stylistNotes" rows="3" placeholder="Actually forest green, not teal. The flash made this look much lighter…">${escape(i.stylistNotes||'')}</textarea><small>Saved with this piece for you and an assistant to read. Update Color family above to change outfit matching now.</small></label><div class="button-row"><button class="btn primary" type="submit">Save piece</button><button class="text-button danger" type="button" data-remove-item="${id}">Remove piece</button></div></div></form>`,'wide-modal');}
function openImport(files=[]){importFiles=files;openModal(`${modalHead('MAKE ROOM FOR SOMETHING NEW','Add to your wardrobe.')}${importTabs('photos')}<form id="import-form"><button class="drop-zone" type="button" data-action="choose-files">${icon('camera',30)}<strong>${files.length?`${files.length} photo${files.length===1?'':'s'} selected`:'Choose photos or drop them here'}</strong><span>JPEG, PNG, or WebP · up to 20 MB each</span></button>${files.length?`<div class="import-list">${files.map((f,n)=>`<label><span>${escape(f.name)}</span><input aria-label="Name for ${escape(f.name)}" name="file-${n}" maxlength="200" required value="${escape(f.name.replace(/\.[^.]+$/,'').replace(/[_-]/g,' '))}"></label>`).join('')}</div>`:''}<p class="field-note">These labels apply to this batch. You can refine each item after importing.</p>${categoryFields({category:category==='All'?'Top':category,role:'base',subcategory:''})}<label>Tags<input name="tags" placeholder="summer, comfortable, everyday"></label>${modesChecks(['Casual'])}<button class="btn primary full" type="submit" ${!files.length?'disabled':''}>${icon('plus',17)} Import ${files.length||''} ${files.length===1?'piece':'pieces'}</button><p class="tiny" id="import-progress">Photos are copied into your local app. Your original files stay unchanged.</p></form>`);const drop=$('.drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging');};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();checkImportFiles([...e.dataTransfer.files]);};}
function importTabs(selected){return `<div class="import-tabs" role="group" aria-label="Import method"><button type="button" data-action="import" aria-pressed="${selected==='photos'}">Your photos</button><button type="button" data-action="web-import" aria-pressed="${selected==='website'}">From a website</button></div>`;}
function openWebImport(url='',error=''){
 const draft=websiteDraft;
 openModal(`${modalHead('BRING A PIECE INTO YOUR WARDROBE','Import from a website')}${importTabs('website')}<form id="web-find-form"><label>Product page or image URL<input name="url" type="url" inputmode="url" autocomplete="off" value="${escape(url||draft?.sourceUrl||'')}" placeholder="https://www.clothing-store.com/product" required><small>Paste a public HTTPS product page, or a direct JPEG, PNG or WebP image link.</small></label><button class="btn secondary full" type="submit">Find product photos</button><p class="web-import-status" id="web-import-status" role="status">${escape(error)}</p></form>${draft?`<form id="web-piece-form"><div class="web-import-source"><span>From ${escape(new URL(draft.sourceUrl).hostname)}</span><a href="${escape(draft.sourceUrl)}" target="_blank" rel="noopener noreferrer">View source page</a></div><h3 class="web-photos-title">Choose the photo for this piece</h3><p class="field-note">Alternate angles belong to the same piece. Choose one clear view.</p><div class="web-photo-grid">${draft.images.map((image,n)=>`<label class="web-photo-choice"><input type="radio" name="image" value="${n}" ${n===0?'checked':''} required aria-label="Choose product photo ${n+1}"><img src="${escape(image.src)}" alt="Product photo option ${n+1}"><span>Photo ${n+1}</span></label>`).join('')}</div><label>Piece name<input name="name" value="${escape(draft.title.slice(0,200))}" maxlength="200" required></label><label>Description<textarea name="description" rows="3" maxlength="2000">${escape(draft.description.slice(0,2000))}</textarea></label>${categoryFields({category:category==='All'?'Top':category,role:'base',subcategory:''})}<div class="form-grid"><label>Color family<select name="color">${Object.keys(PALETTE).map(c=>`<option ${c==='Gray'?'selected':''}>${c}</option>`).join('')}</select></label><label>Formality<select name="formality">${formalityOptions(2)}</select></label></div><label class="check-row"><input name="colorVerified" type="checkbox">I’ve checked the color label</label><label>Tags<input name="tags" placeholder="tailored, everyday, wishlist"></label>${modesChecks(['Casual'])}<p class="field-note">Review the labels before adding this piece. Product photos can look different from the clothing in person.</p><button class="btn primary full" type="submit">Add this piece to my wardrobe</button></form>`:'<div class="web-import-help"><p>We’ll look for product photos, then let you choose an image and review its labels.</p><p>If a store blocks previews or needs JavaScript, use a direct image link or save its photo and upload it with Your photos.</p></div>'}`,'web-import-modal');
}
function checkImportFiles(files){const accepted=files.filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=20*1024*1024);if(accepted.length!==files.length)toast('Only JPEG, PNG, and WebP photos under 20 MB can be imported.');if(accepted.length)openImport(accepted);}
function tags(value){return [...new Set(String(value||'').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean))];}
function subpath(value){return String(value||'').split('/').map(s=>s.trim()).filter(Boolean).join(' / ');}
function rememberSubcategory(i){if(i.subcategory&&!state.subcategories.some(s=>s.category===i.category&&s.path===i.subcategory))state.subcategories.push({category:i.category,path:i.subcategory});}
function categorySetupBanner(){return state.categorySetup?'':`<section class="category-setup-banner" aria-labelledby="category-setup-title"><div class="category-setup-icon">${icon('folder',26)}</div><div><h2 id="category-setup-title">Set up your wardrobe categories</h2><p>Add a complete, expandable category tree for clothing, layers, and accessories. Your current organization stays intact.</p></div><div class="button-row">${button('Preview category tree','category-setup','primary')}<button class="text-button" data-action="dismiss-category-setup" aria-label="Dismiss category setup banner">Not now</button></div></section>`;}
function openCategorySetup(){const plan=categorySetupPlan(state);openModal(`${modalHead('YOUR WARDROBE, ORGANIZED','Build your category tree')}<p class="category-setup-intro">Six fixed top-level categories, with an expandable tree beneath each. This adds <strong>${plan.additions.length} missing subcategories</strong> inside your account. Existing categories, clothing, photos, notes, and corrected colors stay as they are.</p><p class="field-note">Categories organize your photos inside StyleByFire. They do not create or move folders on your computer.</p><div class="category-setup-preview">${categoryTreeMarkup(plan.subcategories,{escape,items:state.items})}</div><div class="button-row category-setup-actions">${button(plan.additions.length?'Add full category tree':'Keep this category tree','install-category-tree','primary','folder')}${button('Cancel','close-modal','secondary')}</div>`,'wide-modal');}
async function saveCategorySetup(install){const previous=state,accountId=auth.user.id;busy=true;try{const result=install?installCategoryTree(state):{state:{...structuredClone(state),categorySetup:{version:1,status:'dismissed'}}};state=result.state;await persist();if(auth.user?.id!==accountId)return;$('#modal').close();render();if(install){openCategories();toast(`Category tree ready. Added ${result.added} subcategories.`);}else toast('Setup dismissed. Reopen it from Organize categories.');}catch(error){if(auth.user?.id===accountId)state=previous;throw error;}finally{busy=false;}}
function openCategories(){openModal(`${modalHead('A PLACE FOR EVERY PIECE','Organize your wardrobe.')}<p class="field-note">The six top-level categories are fixed. Expand a folder to browse its subcategories. Rename or move a piece by editing its category path.</p><div class="category-tree-tools">${button('Set up full category tree','category-setup','secondary','folder')}</div><div class="category-setup-preview">${categoryTreeMarkup(state.subcategories,{escape,items:state.items,removable:true})}</div><form id="category-form"><div class="form-grid"><label>Within<select name="category">${CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></label><label>New subcategory path<input name="path" required placeholder="Jewelry / Rings / Silver"></label></div><button class="btn primary" type="submit">Create subcategory</button></form>`,'wide-modal');}

async function openStudio(id){const item=state.items.find(i=>i.id===id);if(!item)return;editor={id,src:item.src,adjustments:structuredClone(item.adjustments||DEFAULT_ADJUSTMENTS),color:item.color,verified:item.colorVerified,sampling:false,cropping:false,original:false,drawId:0};openModal(`${modalHead('NONDESTRUCTIVE PHOTO EDITOR',escape(item.name))}<div class="photo-editor"><div class="canvas-column"><div class="canvas-wrap"><canvas id="editor-canvas" aria-label="Editable clothing photo"></canvas><div id="crop-box" hidden></div></div><p class="tiny" id="editor-hint">Your original is always preserved. Adjust by eye against the real garment.</p><div class="button-row">${button('Compare original','compare-photo','secondary','camera')}${button('Rotate','rotate-photo','secondary','refresh')}${button('Crop','crop-photo','secondary')}${button('Reset','reset-photo','secondary')}</div></div><div class="photo-controls">${[['exposure','Exposure'],['contrast','Contrast'],['saturation','Saturation'],['temperature','Temperature · cool ↔ warm'],['tint','Tint · green ↔ magenta']].map(([k,label])=>rangeField(k,label,editor.adjustments[k],-100,100,'−','+')).join('')}<div class="form-grid"><label>Color family<select id="editor-color">${Object.keys(PALETTE).map(c=>`<option ${c===item.color?'selected':''}>${c}</option>`).join('')}</select></label><button class="btn secondary sample-button" data-action="sample-color">Sample color</button></div><div id="sample-result" class="tiny">Sample the garment, away from flash highlights.</div><label class="check-row"><input type="checkbox" id="editor-verified" ${item.colorVerified?'checked':''}>Color checked against garment</label>${state.reference?`<details class="reference-details"><summary>Compare background reference</summary><img src="${escape(state.reference)}" alt="Original photography background"><p class="tiny">Blue fabric is not a neutral calibration target. A true gray card under the same light is more reliable.</p></details>`:''}<button class="btn primary full" data-action="save-photo">Save photo adjustments</button></div></div>`,'studio-modal');await repaintEditor();bindCrop();}
async function repaintEditor(){if(!editor)return;const id=++editor.drawId;const snapshot=structuredClone(editor);const temp=document.createElement('canvas');try{await drawPhoto(temp,snapshot.src,snapshot.adjustments,1100,snapshot.original);if(editor?.drawId!==id)return;const canvas=$('#editor-canvas');if(!canvas)return;canvas.width=temp.width;canvas.height=temp.height;canvas.getContext('2d').drawImage(temp,0,0);}catch(e){toast(e.message);}}
function bindCrop(){const c=$('#editor-canvas');let start;
 c.onpointerdown=e=>{if(!editor?.cropping)return;const r=c.getBoundingClientRect();start={x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};c.setPointerCapture(e.pointerId);};
 c.onpointermove=e=>{if(!start||!editor?.cropping)return;const r=c.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));const b=$('#crop-box');b.hidden=false;Object.assign(b.style,{left:Math.min(start.x,x)*100+'%',top:Math.min(start.y,y)*100+'%',width:Math.abs(x-start.x)*100+'%',height:Math.abs(y-start.y)*100+'%'});};
 c.onpointerup=e=>{if(!start||!editor?.cropping)return;const r=c.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));const crop={x:Math.min(x,start.x),y:Math.min(y,start.y),w:Math.abs(x-start.x),h:Math.abs(y-start.y)};start=null;$('#crop-box').hidden=true;editor.cropping=false;c.classList.remove('crosshair');if(crop.w<.05||crop.h<.05){toast('Select a larger crop area.');return;}editor.adjustments.crop=crop;repaintEditor();$('#editor-hint').textContent='Crop applied. Reset restores the full original.';};
 c.onclick=e=>{if(!editor?.sampling)return;const r=c.getBoundingClientRect();const x=Math.floor((e.clientX-r.left)/r.width*c.width),y=Math.floor((e.clientY-r.top)/r.height*c.height);const rgb=c.getContext('2d').getImageData(Math.min(x,c.width-1),Math.min(y,c.height-1),1,1).data;const hex='#'+[...rgb].slice(0,3).map(v=>v.toString(16).padStart(2,'0')).join('');const closest=Object.entries(PALETTE).map(([name,v])=>({name,d:[0,1,2].reduce((sum,n)=>sum+(parseInt(v.slice(1+n*2,3+n*2),16)-rgb[n])**2,0)})).sort((a,b)=>a.d-b.d)[0].name;editor.color=closest;$('#editor-color').value=closest;$('#sample-result').innerHTML=`<span class="swatch" style="--swatch:${hex}"></span> ${hex.toUpperCase()} · nearest family: ${closest}. Check by eye.`;editor.sampling=false;c.classList.remove('crosshair');};
}
async function backup(){toast('Preparing a complete wardrobe backup…');await saveQueue.catch(()=>{});const snapshot=structuredClone(state);const assets={};for(const src of new Set([...snapshot.items.map(i=>i.src),snapshot.reference].filter(Boolean))){const res=await fetch(src);if(!res.ok)throw Error('A photo could not be included in the backup.');const blob=await res.blob();assets[src]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});}const blob=new Blob([JSON.stringify({format:'stylebyfire-backup',version:1,exportedAt:new Date().toISOString(),state:snapshot,assets})],{type:'application/json'});const url=URL.createObjectURL(blob);const a=Object.assign(document.createElement('a'),{href:url,download:`wardrobe-backup-${new Date().toISOString().slice(0,10)}.json`});a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Backup exported with your photos, looks, and preferences.');}
async function prepareRestore(file){if(file.size>250*1024*1024)throw Error('This backup is larger than 250 MB.');const backup=JSON.parse(await file.text());if(backup.format!=='stylebyfire-backup'||backup.version!==1||!backup.assets)throw Error('Please choose a complete StyleByFire backup.');validateState(backup.state);const srcs=new Set([...backup.state.items.map(i=>i.src),backup.state.reference].filter(Boolean));for(const src of srcs)if(typeof backup.assets[src]!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(backup.assets[src]))throw Error('The backup is missing a valid photo.');window.pendingRestore=backup;openModal(`${modalHead('RESTORE WARDROBE','Replace this wardrobe?')}<p>This backup contains ${backup.state.items.length} pieces and ${backup.state.looks.length} looks. It will replace your current wardrobe and preferences. Export your current wardrobe first if you want to keep it.</p><div class="button-row">${button('Export current wardrobe','backup')}${button('Restore this backup','confirm-restore','primary')}</div>`);}
async function performRestore(){const backup=window.pendingRestore;if(!backup)return;busy=true;$$('#modal button').forEach(b=>b.disabled=true);try{const replacements={};for(const src of new Set([...backup.state.items.map(i=>i.src),backup.state.reference].filter(Boolean))){const data=backup.assets[src];const bytes=Uint8Array.from(atob(data.split(',')[1]),c=>c.charCodeAt(0));const blob=new Blob([bytes],{type:data.match(/^data:([^;]+)/)[1]});await loadPhoto(URL.createObjectURL(blob)).catch(()=>{throw Error('The backup contains a photo that cannot be decoded.');});replacements[src]=(await api('/api/images',{method:'POST',body:blob})).src;}const next=structuredClone(backup.state);for(const i of next.items)i.src=replacements[i.src];if(next.reference)next.reference=replacements[next.reference];await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(next)});state=next;weeklyDraft=null;weekEditor=null;locked=[];outfit=null;delete window.pendingRestore;$('#modal').close();render();toast('Your wardrobe has been restored.');}finally{busy=false;$$('#modal button').forEach(b=>b.disabled=false);}}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-nav]');if(!el||el.disabled||busy)return;try{
 if(el.dataset.weekLock){await toggleWeeklyDayLock(el.dataset.weekLock);return;}
 if(el.dataset.weekEdit){openWeeklyEditor(el.dataset.weekEdit,el.dataset.weekReplace||null);return;}
 if(el.dataset.weekChange&&weekEditor){const item=state.items.find(item=>item.id===el.dataset.weekChange);weekEditor.replaceId=item.id;weekEditor.category=item.category;weekEditor.query='';renderWeeklyEditor('#week-piece-search',false);return;}
 if(el.dataset.weekRemove&&weekEditor){weekEditor.itemIds=weekEditor.itemIds.filter(id=>id!==el.dataset.weekRemove);if(weekEditor.replaceId===el.dataset.weekRemove)weekEditor.replaceId=null;renderWeeklyEditor('#week-piece-search');return;}
 if(el.dataset.weekPick&&weekEditor){const piece=state.items.find(item=>item.id===el.dataset.weekPick),items=weekEditor.itemIds.map(id=>state.items.find(item=>item.id===id)).filter(Boolean);const next=changeWeeklySelection(items,piece,weekEditor.replaceId);replaceWeeklyDay(state,state.weeklyPlanner.plan,weekEditor.dayId,next.map(item=>item.id));weekEditor.itemIds=next.map(item=>item.id);weekEditor.replaceId=null;renderWeeklyEditor(`[data-week-pick="${piece.id}"]`);return;}
 if(el.dataset.weekOpen){const day=state.weeklyPlanner?.plan?.days.find(day=>day.id===el.dataset.weekOpen);if(!day)return;mode=day.mode;buildMethod='stylist';locked=[...day.itemIds];const items=day.itemIds.map(id=>state.items.find(item=>item.id===id)).filter(Boolean);outfit=manualOutfit(items,mode,state);page='designer';category='All';render();window.scrollTo(0,0);return;}
 if(el.dataset.nav){e.preventDefault();page=el.dataset.nav;category='All';if(page==='guidelines')ruleMode=mode;render();window.scrollTo(0,0);return;}
 if(el.dataset.category){category=el.dataset.category;subfilter='';render();return;}
 if(el.dataset.favorite){const i=state.items.find(i=>i.id===el.dataset.favorite);i.favorite=!i.favorite;await persist();render();return;}
 if(el.dataset.rotateDetail){if(itemDraft?.id!==el.dataset.rotateDetail)return;itemDraft.adjustments={...DEFAULT_ADJUSTMENTS,...itemDraft.adjustments,rotation:((itemDraft.adjustments?.rotation||0)+Number(el.dataset.turn)+360)%360};$('#detail-image').innerHTML=photo(itemDraft,'',true);renderAdjustedImages($('#detail-image'));return;}
 if(el.dataset.edit)return openItem(el.dataset.edit);
 if(el.dataset.studio)return await openStudio(el.dataset.studio);
 if(el.dataset.buildMethod){if(buildMethod===el.dataset.buildMethod)return;buildMethod=el.dataset.buildMethod;if(buildMethod==='manual')setManualPieces(outfit?.items||[]);else locked=(outfit?.items||[]).map(i=>i.id);render();$(`[data-build-method="${buildMethod}"]`)?.focus({preventScroll:true});return;}
 if(el.dataset.choosePiece){const piece=state.items.find(i=>i.id===el.dataset.choosePiece);if(!piece)return;const previous=outfit?.items||[];const next=toggleOutfitPiece(previous,piece);setManualPieces(next);render();$(`#outfit-picker-grid [data-choose-piece="${piece.id}"]`)?.focus({preventScroll:true});const replaced=previous.filter(i=>!next.some(n=>n.id===i.id));toast(next.some(i=>i.id===piece.id)?`${piece.name} added.${replaced.length?' Replaced '+replaced.map(i=>i.name).join(', ')+'.':''}`:`${piece.name} removed from this outfit.`);return;}
 if(el.dataset.pin){const id=el.dataset.pin;locked=locked.includes(id)?locked.filter(x=>x!==id):[...locked,id];if(outfit?.errors.length)outfit=null;render();return;}
 if(el.dataset.mode){mode=el.dataset.mode;if(buildMethod==='manual')setManualPieces(outfit?.items||[]);else outfit=null;render();return;}
 if(el.dataset.ruleMode){ruleMode=el.dataset.ruleMode;render();return;}
 if(el.dataset.openLook){buildMethod='stylist';const l=state.looks.find(l=>l.id===el.dataset.openLook);mode=l.mode;locked=[...l.itemIds];const pieces=l.itemIds.map(id=>state.items.find(i=>i.id===id)).filter(Boolean);outfit={items:pieces,errors:[],...assessOutfit(pieces,l.mode,state.rules[l.mode],state.profile)};page='designer';category='All';render();return;}
 if(el.dataset.deleteLook){state.looks=state.looks.filter(l=>l.id!==el.dataset.deleteLook);await persist();render();toast('Look removed. Your clothing stays in the wardrobe.');return;}
 if(el.dataset.removeItem){const i=state.items.find(i=>i.id===el.dataset.removeItem);openModal(`${modalHead('REMOVE FROM WARDROBE','Remove this piece?')}<p>${escape(i.name)} will be removed from your wardrobe, saved looks, and weekly outfits, including locked days. Its original photo file will stay on your computer.</p><button class="btn primary" data-confirm-remove="${i.id}">Remove piece</button>`);return;}
 if(el.dataset.confirmRemove){const id=el.dataset.confirmRemove;state.items=state.items.filter(i=>i.id!==id);state.looks=state.looks.map(l=>({...l,itemIds:l.itemIds.filter(x=>x!==id)}));if(state.weeklyPlanner?.plan)for(const day of state.weeklyPlanner.plan.days)day.itemIds=day.itemIds.filter(x=>x!==id);locked=locked.filter(x=>x!==id);outfit=null;await persist();$('#modal').close();render();toast('Piece removed. Original photo preserved.');return;}
 if(el.dataset.removeSub){e.preventDefault();const [c,p]=el.dataset.removeSub.split('|');if(state.items.some(i=>i.category===c&&(i.subcategory===p||i.subcategory.startsWith(p+' / '))))return toast('This path contains clothing. Move those pieces before removing it.');state.subcategories=state.subcategories.filter(s=>!(s.category===c&&s.path===p));await persist();openCategories();return;}
 switch(el.dataset.action){
  case 'week-save-pieces':await saveWeeklyPieces();break;
  case 'week-stop-swap':if(weekEditor){weekEditor.replaceId=null;renderWeeklyEditor('#week-piece-search');}break;
  case 'neutral-defaults':case 'neutral-none':$$('[name=neutralColors]').forEach(i=>i.checked=el.dataset.action==='neutral-defaults'&&NEUTRAL_COLORS.includes(i.value));break;
  case 'select-visible':filteredItems().forEach(i=>selectedItems.add(i.id));render();break;
  case 'clear-selection':selectedItems.clear();render();break;
  case 'bulk-edit':bulkDraft=null;openBulkEdit();break;
  case 'bulk-back':openBulkEdit();break;
  case 'bulk-apply':await applyBulkPreview();break;
  case 'bulk-undo':await applyBulkUndo();break;

  case 'auth-login':authMode='login';renderAuth();break;
  case 'auth-register':authMode='register';renderAuth();break;
  case 'auth-demo':{const original=el.innerHTML;el.disabled=true;el.textContent='Opening the product-photo demo…';try{await authAction('demo');}finally{if(el.isConnected){el.disabled=false;el.innerHTML=original;}}break;}
  case 'account':openAccount();break;
  case 'sign-out':await saveQueue;auth=await api('/api/auth/logout',{method:'POST'});clearAccountView();authMode=auth.needsSetup?'register':'login';renderAuth();accountEvents.postMessage('changed');break;

  case 'refresh-inventory':{busy=true;el.textContent='Refreshing…';try{await saveQueue;const result=await api('/api/inventory/refresh',{method:'POST'});state=validateState(result.state);category='All';query='';subfilter='';colorfilter='';favoritesOnly=false;outfit=null;render();toast(`${result.added?`Added ${result.added} new pieces`:'Inventory is up to date'}. Your notes and edits are preserved.${result.skipped.length?` Skipped ${result.skipped.length} unsupported or oversized files.`:''}`);}finally{busy=false;if(el.isConnected)el.textContent='Refresh inventory';}break;}
  case 'import':openImport();break;case 'web-import':websiteDraft=null;openWebImport();break;case 'choose-files':$('#import-files').click();break;
  case 'close-modal':closeMannequin();$('#modal').close();editor=null;weekEditor=null;break;
  case 'mannequin':await saveQueue;await openMannequin({state,itemIds:outfit?.items.map(i=>i.id)||[],mode,api,openModal,modalHead,photo,escape,accountId:auth.user.id,savedPreview:outfitPreview.selected()});break;
  case 'copy-outfit-request':{const message=outfitPreview.requestMessage();if(!message)break;try{await navigator.clipboard.writeText(message);toast('Copied. Send it to Codex; the finished image will appear automatically.');}catch{$('#outfit-codex-request')?.focus();$('#outfit-codex-request')?.select();toast('Select and copy the request, then send it to Codex.');}break;}
  case 'refresh-outfit-preview':await outfitPreview.update(state,outfit?.items||[],mode,{refresh:true,automatic:buildMethod==='manual'&&autoMannequin});break;
  case 'build-manually':buildMethod='manual';setManualPieces(outfit?.items||[]);render();scrollToDesignerSection('clothing-picker');$('#picker-search')?.focus({preventScroll:true});break;
  case 'clear-outfit':setManualPieces([]);render();$('#picker-search')?.focus({preventScroll:true});toast('Outfit cleared. Your wardrobe and saved previews are unchanged.');break;
  case 'go-designer':page='designer';category='All';render();break;
  case 'favorites-filter':favoritesOnly=!favoritesOnly;render();break;
  case 'clear-filters':reviewFilter='';availabilityFilter='';category='All';query='';subfilter='';colorfilter='';favoritesOnly=false;render();break;
  case 'categories':openCategories();break;
  case 'category-setup':openCategorySetup();break;
  case 'install-category-tree':await saveCategorySetup(true);break;
  case 'dismiss-category-setup':await saveCategorySetup(false);break;
  case 'clear-pins':locked=[];if(outfit?.errors.length)outfit=null;render();break;
  case 'view-outfit':scrollToDesignerSection('outfit-workspace');break;
  case 'browse-clothing':scrollToDesignerSection('clothing-picker');break;
  case 'generate':{const required=buildMethod==='manual'?(outfit?.items||[]).map(i=>i.id):locked;const suggested=generateOutfit(state.items,mode,state.rules[mode],state.profile,required,++seed);if(buildMethod==='manual'&&suggested.items.length>20)throw Error('Remove a few accessories before adding suggestions. Mannequin previews support up to 20 pieces.');outfit=suggested;render();scrollToDesignerSection('outfit-workspace');break;}
  case 'save-look':openModal(`${modalHead('KEEP THE COMBINATION','Give this look a name.')}<form id="look-form"><label>Look name<input name="name" value="${escape(mode+' · '+new Date().toLocaleDateString())}" required maxlength="100" autofocus></label><button class="btn primary full" type="submit">Save to lookbook</button></form>`);break;
  case 'reset-rules':state.rules[ruleMode]=structuredClone(DEFAULT_RULES[ruleMode]);outfit=null;await persist();render();toast('Defaults restored for '+ruleMode+'.');break;
  case 'backup':await backup();break;
  case 'restore':$('#restore-file').click();break;
  case 'confirm-restore':await performRestore();break;
  case 'reference':$('#reference-file').click();break;
  case 'compare-photo':editor.original=!editor.original;el.textContent=editor.original?'Return to edits':'Compare original';await repaintEditor();break;
  case 'rotate-photo':editor.original=false;editor.adjustments.rotation=(editor.adjustments.rotation+90)%360;await repaintEditor();break;
  case 'reset-photo':editor.adjustments=structuredClone(DEFAULT_ADJUSTMENTS);editor.original=false;for(const input of $$('.photo-controls input[type=range]')){input.value=0;input.previousElementSibling.value=0;}await repaintEditor();toast('Adjustments reset. Save to keep this change.');break;
  case 'crop-photo':editor.adjustments.crop=null;editor.adjustments.rotation=0;editor.original=false;editor.cropping=true;editor.sampling=false;await repaintEditor();$('#editor-canvas').classList.add('crosshair');$('#editor-hint').textContent='Drag a rectangle around the garment. Crop starts from the unrotated full photo.';break;
  case 'sample-color':editor.sampling=true;editor.cropping=false;$('#editor-canvas').classList.add('crosshair');$('#editor-hint').textContent='Click the garment to suggest its nearest color family. Avoid the background and flash glare.';break;
  case 'save-photo':{const i=state.items.find(i=>i.id===editor.id);i.adjustments=structuredClone(editor.adjustments);i.color=$('#editor-color').value;i.colorVerified=$('#editor-verified').checked;refreshOutfitAssessment();await persist();$('#modal').close();editor=null;render();toast('Photo adjustments saved. Your original is unchanged.');break;}
 }
 }catch(err){toast(err.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='picker-search'){pickerQuery=e.target.value;$('#outfit-picker-grid').innerHTML=renderPicker();renderAdjustedImages($('#outfit-picker-grid'));}if(e.target.id==='search'){query=e.target.value;$('#collection-grid').innerHTML=collectionGrid();renderAdjustedImages($('#collection-grid'));}if(e.target.type==='range'){e.target.previousElementSibling.value=e.target.value;if(editor&&e.target.closest('.photo-controls')){editor.adjustments[e.target.name]=Number(e.target.value);editor.original=false;repaintEditor();}}});
document.addEventListener('change',async e=>{try{const t=e.target;if(t.id==='auto-mannequin'){autoMannequin=t.checked;try{localStorage.setItem('stylebyfire-auto-preview:'+auth.user.id,String(autoMannequin));}catch{}await outfitPreview.update(state,outfit?.items||[],mode,{automatic:buildMethod==='manual'&&autoMannequin});return;}if(t.dataset.selectItem){t.checked?selectedItems.add(t.dataset.selectItem):selectedItems.delete(t.dataset.selectItem);$('#bulk-count').textContent=selectedItems.size+' selected';return;}if(t.id==='review-filter'||t.id==='availability-filter'){if(t.id==='review-filter')reviewFilter=t.value;else availabilityFilter=t.value;render();return;}if(['subfilter','colorfilter','sort'].includes(t.id)){if(t.id==='subfilter')subfilter=t.value;if(t.id==='colorfilter')colorfilter=t.value;if(t.id==='sort')sort=t.value;render();}if(t.id==='item-category'){$('#item-role').innerHTML=roleOptions(t.value,'base');$('#subcategory-list').innerHTML=subcategoryOptions(t.value);const input=$('#modal input[name=subcategory]');if(input)input.value='';}if(t.id==='import-files'){checkImportFiles([...t.files]);t.value='';}if(t.id==='restore-file'){if(t.files[0])await prepareRestore(t.files[0]);t.value='';}if(t.id==='reference-file'){const f=t.files[0];if(f){if(f.size>20*1024*1024)throw Error('Please use a reference photo smaller than 20 MB.');state.reference=(await api('/api/images',{method:'POST',body:f})).src;await persist();render();toast('Background reference updated.');}t.value='';}}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{
 if(e.target.id==='week-piece-category'&&weekEditor){weekEditor.category=e.target.value;$('#week-piece-options').innerHTML=weeklyEditorOptions(state,weekEditor,{escape,photo});renderAdjustedImages($('#week-piece-options'));return;}
 const form=e.target.closest('#weekly-form');if(!form||!state||busy)return;
 weeklyDraft=weeklySettingsFromForm(new FormData(form),weeklyDraft||state.weeklyPlanner?.settings||defaultWeeklySettings(),state.weeklyPlanner?.plan);
 for(const day of weeklyDraft.days){form.elements['mode-'+day.id].disabled=!day.enabled||state.weeklyPlanner?.plan?.days.some(saved=>saved.id===day.id&&saved.locked);form.querySelector(`[data-week-day="${day.id}"]`).classList.toggle('is-off',!day.enabled);}
 for(const [id,rule] of Object.entries(weeklyDraft.reuse))form.elements['limit-'+id].disabled=!rule.enabled;
 $('#weekly-settings-summary').textContent=weeklyDraft.days.filter(day=>day.enabled).length+' days on · choose modes & reuse limits';
 $('#weekly-save-note').textContent='Unsaved settings. Generate week also saves them.';
 const stale=$('#weekly-stale');if(stale)stale.hidden=JSON.stringify(weeklyDraft)===JSON.stringify(state.weeklyPlanner.plan.settings);
});
document.addEventListener('input',e=>{if(e.target.id==='week-piece-search'&&weekEditor){weekEditor.query=e.target.value;$('#week-piece-options').innerHTML=weeklyEditorOptions(state,weekEditor,{escape,photo});renderAdjustedImages($('#week-piece-options'));}});

document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const form=e.target;const data=new FormData(form);try{
 if(form.id==='weekly-form'){await saveWeeklyForm(form,e.submitter?.value||'save');return;}
 if(form.id==='bulk-form'){previewBulkForm(data);return;}
 if(form.id==='auth-form'){const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await authAction(authMode==='register'?'register':'login',Object.fromEntries(data));}catch(err){$('#auth-error').textContent=err.message;submit.disabled=false;}return;}

 if(form.id==='web-find-form'){
  const url=data.get('url').trim(),accountId=auth.user.id,controller=new AbortController();webImportController=controller;busy=true;websiteDraft=null;$$('#modal button').forEach(b=>b.disabled=true);$('#web-import-status').textContent='Finding and downloading product photos…';
  try{const result=await api('/api/web-import/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url}),signal:controller.signal,accountId});if(webImportController!==controller||auth.user?.id!==accountId)return;websiteDraft=result;openWebImport(url);}catch(err){if(webImportController===controller&&auth.user?.id===accountId)openWebImport(url,err.message);}finally{if(webImportController===controller){webImportController=null;busy=false;$$('#modal button').forEach(b=>b.disabled=false);}}return;
 }
 if(form.id==='web-piece-form'){
  const image=websiteDraft?.images[Number(data.get('image'))];if(!image)throw Error('Choose a product photo first.');
  const item={id:crypto.randomUUID(),name:data.get('name').trim(),description:data.get('description').trim(),category:data.get('category'),role:data.get('role'),subcategory:subpath(data.get('subcategory')),tags:tags(data.get('tags')),modes:data.getAll('modes'),color:data.get('color'),colorVerified:data.has('colorVerified'),pattern:'Solid',formality:Number(data.get('formality')),warmth:1,favorite:false,src:image.src,sourceUrl:websiteDraft.sourceUrl,sourceImageUrl:image.originalUrl,sourceName:new URL(websiteDraft.sourceUrl).hostname,notes:'',stylistNotes:'',adjustments:structuredClone(DEFAULT_ADJUSTMENTS)};
  const next=structuredClone(state);next.items.push(item);validateState(next);state=next;rememberSubcategory(item);await persist();websiteDraft=null;$('#modal').close();page='wardrobe';category=item.category;query='';subfilter='';colorfilter='';favoritesOnly=false;outfit=null;render();toast('Website photo imported. Open the piece to refine its labels or add notes.');return;
 }
 if(form.id==='item-form'){const item=state.items.find(i=>i.id===form.dataset.id);Object.assign(item,{name:data.get('name').trim(),description:data.get('description').trim(),category:data.get('category'),role:data.get('role'),subcategory:subpath(data.get('subcategory')),tags:tags(data.get('tags')),modes:data.getAll('modes'),color:data.get('color'),secondaryColor:data.get('secondaryColor')||'',availability:data.get('availability'),colorVerified:data.has('colorVerified'),pattern:data.get('pattern'),formality:Number(data.get('formality')),warmth:Number(data.get('warmth')),notes:data.get('notes'),stylistNotes:data.get('stylistNotes'),adjustments:itemDraft?.id===item.id?structuredClone(itemDraft.adjustments):item.adjustments});rememberSubcategory(item);refreshOutfitAssessment();await persist();$('#modal').close();render();toast('Piece updated.');}
 if(form.id==='import-form'){busy=true;const pending=[];$$('#modal button').forEach(b=>b.disabled=true);try{for(let n=0;n<importFiles.length;n++){const f=importFiles[n];$('#import-progress').textContent=`Importing ${n+1} of ${importFiles.length}…`;const url=URL.createObjectURL(f);try{const im=await loadPhoto(url);if(im.width*im.height>80000000)throw Error('This photo is too large to edit. Choose one under 80 megapixels.');}finally{URL.revokeObjectURL(url);}const {src}=await api('/api/images',{method:'POST',body:f});pending.push({id:crypto.randomUUID(),name:data.get('file-'+n).trim(),category:data.get('category'),role:data.get('role'),subcategory:subpath(data.get('subcategory')),tags:tags(data.get('tags')),modes:data.getAll('modes'),color:'Gray',colorVerified:false,pattern:'Solid',formality:2,warmth:1,favorite:false,src,notes:'Review color, formality, pattern, and suitability after import.',stylistNotes:'',adjustments:structuredClone(DEFAULT_ADJUSTMENTS)});}state.items.push(...pending);pending.forEach(rememberSubcategory);await persist();$('#modal').close();page='wardrobe';query='';subfilter='';colorfilter='';favoritesOnly=false;category=data.get('category');outfit=null;render();toast(`${pending.length} ${pending.length===1?'piece':'pieces'} imported. Open each to refine its labels.`);}finally{busy=false;$$('#modal button').forEach(b=>b.disabled=false);}}
 if(form.id==='stylist-form'){state.profile={name:data.get('name').trim(),palette:data.get('palette'),silhouette:data.get('silhouette'),preferredTags:tags(data.get('preferredTags')),avoidTags:tags(data.get('avoidTags')),favoriteBias:Number(data.get('favoriteBias')),adventure:Number(data.get('adventure')),warmth:Number(data.get('warmth')),notes:data.get('notes'),ignoreSockPatterns:data.has('ignoreSockPatterns'),ignoreNeutralColors:data.has('ignoreNeutralColors'),neutralColors:data.getAll('neutralColors')};refreshOutfitAssessment();await persist();toast('Stylist preferences saved. Remix to try new suggestions.');}
 if(form.id==='rules-form'){if(Number(data.get('minFormality'))>Number(data.get('maxFormality')))throw Error('Minimum formality must be at or below the maximum.');state.rules[ruleMode]={minFormality:Number(data.get('minFormality')),maxFormality:Number(data.get('maxFormality')),maxPatterns:Number(data.get('maxPatterns')),maxColors:Number(data.get('maxColors')),requireSocks:data.has('requireSocks'),includeLayer:data.has('includeLayer'),includeAccessory:data.has('includeAccessory'),note:data.get('note'),...(ruleMode==='Golf'?{golfCollaredTop:data.has('golfCollaredTop'),golfTailoredBottoms:data.has('golfTailoredBottoms'),golfAllowTrainers:data.has('golfAllowTrainers')}:{})};outfit=null;await persist();toast(ruleMode+' guidelines saved.');}
 if(form.id==='look-form'){state.looks.push({id:crypto.randomUUID(),name:data.get('name').trim(),mode,itemIds:outfit.items.map(i=>i.id),createdAt:new Date().toISOString()});await persist();$('#modal').close();toast('Look saved to your lookbook.');}
 if(form.id==='category-form'){const category=data.get('category'),path=subpath(data.get('path'));if(!path)throw Error('Enter a subcategory name.');if(!state.subcategories.some(s=>s.category===category&&s.path===path))state.subcategories.push({category,path});await persist();openCategories();toast('Subcategory created.');}
 }catch(err){toast(err.message);}});
$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();else{editor=null;weekEditor=null;}});
window.addEventListener('beforeunload',e=>{if(busy||saveFailure){e.preventDefault();e.returnValue='';}});
try{auth=await api('/api/auth');authMode=auth.needsSetup?'register':'login';if(auth.user)await loadAccount();else renderAuth();}catch(e){$('#app').innerHTML=`<div class="loading"><h1>Let’s reconnect.</h1><p>${escape(e.message)}</p><p>Start the local server, then reload this page.</p></div>`;}

$('#modal').addEventListener('close',()=>{if(page==='designer'&&auth.user&&state)void outfitPreview.update(state,outfit?.items||[],mode,{refresh:true,automatic:buildMethod==='manual'&&autoMannequin});});

document.addEventListener('visibilitychange',()=>{if(document.hidden)outfitPreview.pause();else if(page==='designer'&&auth.user&&state)void outfitPreview.update(state,outfit?.items||[],mode,{refresh:true,automatic:buildMethod==='manual'&&autoMannequin});});
